import sys;sys.path.insert(0,'/mnt/c/WSL/davita/translations/xhi22')
from lib import *
r=[]
r.append(R(6562343,"थाइम वाले भुने हुए मशरूम",
"इन स्वादिष्ट थाइम वाले भुने हुए मशरूम के साथ अपने मधुमेह के अनुकूल भोजन को और बेहतर बनाएँ। स्वाद से भरपूर और बिल्कुल सही मसालों वाले ये मशरूम किसी भी भोजन में एक स्वादिष्ट जोड़ हैं। ऐसा व्यंजन अनुभव करें जो संतोषजनक भी है और आपके मधुमेह प्रबंधन के लक्ष्यों में सहायक भी।",
"4","लगभग ¾ कप",
["1 पाउंड मशरूम (जैसे क्रेमिनी या बटन मशरूम) (चार टुकड़ों में कटे हुए)","2 बड़े चम्मच जैतून का तेल","2 कली लहसुन (बारीक कटी हुई)","1 बड़ा चम्मच ताज़ा थाइम की पत्तियाँ","1/8 छोटा चम्मच कोशर नमक (वैकल्पिक)","1/8 छोटा चम्मच काली मिर्च (वैकल्पिक)","1 बड़ा चम्मच नीबू का रस (वैकल्पिक, खट्टे स्वाद के लिए)"],
["एक बड़ी कड़ाही में मध्यम-तेज़ आँच पर जैतून का तेल गरम करें।","कटे हुए मशरूम कड़ाही में डालें और बीच-बीच में चलाते हुए लगभग 6–8 मिनट पकाएँ, जब तक मशरूम अपनी नमी न छोड़ दें और सुनहरे भूरे न हो जाएँ।","कड़ाही में कटा हुआ लहसुन और ताज़ी थाइम की पत्तियाँ डालें। लहसुन की खुशबू आने तक 1–2 मिनट और भूनें।","मशरूम में नमक (वैकल्पिक) और काली मिर्च डालें, मात्रा स्वादानुसार रखें। चाहें तो खट्टे स्वाद के लिए मशरूम पर नीबू का रस डालें।","स्वाद बराबर फैलाने के लिए चलाते हुए मशरूम को 1 मिनट और पकाते रहें।","आँच से उतारें और थाइम वाले भुने मशरूम को परोसने के बर्तन में निकालें।"]))
r.append(R(6563395,"सब्ज़ियों का ब्रेकफ़ास्ट हैश",
"यह सब्ज़ियों का ब्रेकफ़ास्ट हैश आपके दिन की भरपेट शुरुआत करने का एक बढ़िया तरीका है और ब्रंच के लिए भी बहुत अच्छा है! आप अपनी पसंदीदा किसी भी बिना स्टार्च वाली सब्ज़ी को डालकर इस हैश को अपनी पसंद के अनुसार बना सकते हैं।",
"4","1 कप",
["2 बड़े चम्मच कैनोला तेल","1/2 कप पीला प्याज़ (टुकड़ों में कटा हुआ)","1 मध्यम शिमला मिर्च (टुकड़ों में कटी हुई)","2 मध्यम तोरी (टुकड़ों में कटी हुई)","1 मध्यम आलू (टुकड़ों में कटा हुआ)","1/2 छोटा चम्मच नमक (बाँटकर उपयोग)","1/2 छोटा चम्मच काली मिर्च","1 कप चेरी टमाटर (आधे कटे हुए)","2 कली लहसुन (बारीक कटी हुई)","1 छोटा चम्मच स्मोक्ड पैपरिका","1/2 छोटा चम्मच जीरा","4 बड़े अंडे"],
["एक बड़ी कड़ाही में मध्यम आँच पर तेल गरम करें।","कटे हुए प्याज़ और आलू डालें और प्याज़ के नरम होने तक पकाएँ।","कटी हुई शिमला मिर्च और तोरी डालकर मिलाएँ और काली मिर्च और ¼ छोटा चम्मच नमक डालें। सब्ज़ियों के नरम होने तक 5–7 मिनट पकाएँ।","चेरी टमाटर, कटा हुआ लहसुन, स्मोक्ड पैपरिका, जीरा, ¼ छोटा चम्मच नमक और काली मिर्च डालें। टमाटर के नरम होने के लिए 3–5 मिनट और पकाएँ।","सब्ज़ियों के मिश्रण में चार गड्ढे बनाएँ।","हर गड्ढे में एक अंडा तोड़कर डालें। ¼ छोटा चम्मच नमक और काली मिर्च छिड़कें।","कड़ाही को ढक दें और 5–7 मिनट पकाएँ, या जब तक अंडे आपकी पसंद के अनुसार न पक जाएँ।"]))
r.append(R(6563572,"पेस्टो चिकन रैप",
"ये स्वादिष्ट रैप बचे हुए बेक्ड चिकन का उपयोग करने और साथ ही कुछ ताज़ी सब्ज़ियाँ खाने का एक अच्छा तरीका हैं। इन्हें पाँच मिनट या उससे कम समय में बनाना आसान है!",
"2","1 रैप",
["4 औंस रेशों में कटा पका हुआ चिकन ब्रेस्ट (लगभग 1/2 कप)","1 बड़ा चम्मच तैयार पेस्टो","2 साबुत कम कार्ब वाले साबुत अनाज के टॉर्टिला रैप","4 पत्ते बिब या रोमेन लेट्यूस के पत्ते","4 छोटे चम्मच फ़ैट-फ़्री फ़ेटा चीज़","2 बड़े चम्मच भुनी हुई लाल शिमला मिर्च की पट्टियाँ","1 छोटा टमाटर (पतला कटा हुआ)"],
["एक छोटे कटोरे में रेशों में कटे चिकन को पेस्टो के साथ मिलाएँ और अलग रख दें।","टॉर्टिला को किसी समतल सतह पर रखें। लेट्यूस के पत्तों को टॉर्टिला पर रखें, टॉर्टिला के बाहरी किनारे का लगभग 1 इंच हिस्सा खाली छोड़ दें।","चिकन को टॉर्टिला के बीच बाँटें और उसे लेट्यूस पर फैलाएँ।","चिकन के ऊपर फ़ेटा चीज़ छिड़कें और लाल शिमला मिर्च की पट्टियाँ और टमाटर के स्लाइस डालें।","टॉर्टिला के दो आमने-सामने के किनारों को लगभग 1 इंच अंदर की ओर मोड़ें। बाक़ी किनारों में से एक को लें और उसे दूसरे किनारे की ओर कसकर लपेटें। ध्यान रखें कि भरावन बाहर न गिरे। लपेटे हुए रैप को आधा काटें।","चाहें तो साथ में साइड सलाद परोसें।"]))
r.append(R(6564680,"अरुगुला, नाशपाती, अखरोट और पेकोरिनो सलाद",
"बहुत सरल फिर भी सुंदर, यह दक्षिणी इटली का एक क्लासिक सलाद है।",
"6","रेसिपी का 1/6 भाग",
["6 औंस अरुगुला","1 मध्यम नाशपाती","1/4 कप अखरोट के आधे टुकड़े","1/2 औंस पेकोरिनो रोमानो चीज़ (ठंडा, ताज़ा छीला हुआ)","2 बड़े चम्मच बाल्सैमिक सिरका","2 बड़े चम्मच एक्स्ट्रा वर्जिन जैतून का तेल","1/2 छोटा चम्मच काली मिर्च"],
["अरुगुला को एक बड़े सलाद कटोरे में रखें। नाशपाती को जितना हो सके पतला काटें और अरुगुला के ऊपर रखें। अखरोट के आधे टुकड़े छिड़कें। सब्ज़ी छीलने वाले पीलर से 1/2 औंस पेकोरिनो सलाद के कटोरे के ऊपर छीलें।","सलाद पर बाल्सैमिक सिरका छिड़कें। सलाद पर एक्स्ट्रा वर्जिन जैतून का तेल छिड़कें। काली मिर्च डालें। अच्छी तरह मिलाएँ। परोसें।"]))
r.append(R(6565884,"भुने हुए पीले और हरे स्क्वैश",
"भुने हुए पीले और हरे स्क्वैश की यह रेसिपी एक मधुमेह के अनुकूल साइड डिश है जिसमें चटख रंग भूनने से मिले भरपूर, कैरामेलाइज़्ड स्वाद के पूरक बनते हैं।",
"4","½ कप",
["1 मध्यम पीला स्क्वैश (अर्धचंद्राकार टुकड़ों में कटा हुआ)","1 मध्यम तोरी","2 बड़े चम्मच जैतून का तेल","1 छोटा चम्मच सूखा ओरेगानो","1/4 छोटा चम्मच नमक","1/4 छोटा चम्मच काली मिर्च"],
["ओवन को 400 डिग्री F पर पहले से गरम करें।","एक बड़े कटोरे में स्क्वैश को जैतून का तेल, सूखा ओरेगानो, नमक और काली मिर्च के साथ मिलाएँ।","बेकिंग शीट पर रखें और नरम होने तक 15–20 मिनट भूनें।"]))
r.append(R(6566186,"ग्रिल्ड चिकन रैप",
"इन स्वादिष्ट डिनर रैप में ग्रिल्ड चिकन ब्रेस्ट और प्याज़ भरे जाते हैं। चिकन और प्याज़ को इनडोर या आउटडोर ग्रिल पर पकाएँ।",
"2","1 रैप",
["1/2 पाउंड बिना हड्डी और बिना त्वचा वाली चिकन ब्रेस्ट","1/4 छोटा चम्मच काली मिर्च","1/2 कप प्याज़ (लगभग 1/4 इंच मोटे स्लाइस में कटा हुआ)","1/4 कप बिना चीनी मिला बारबेक्यू सॉस","2 साबुत गेहूँ के आटे के टॉर्टिला (8 इंच)","1/2 कप लेट्यूस (बारीक कटा हुआ)","1/2 कप ताज़े टमाटर (टुकड़ों में कटे हुए)"],
["स्टोव-टॉप ग्रिल को पहले से गरम करें।","चिकन से दिखाई देने वाली चर्बी हटाएँ और उस पर काली मिर्च छिड़कें।","चिकन और प्याज़ के स्लाइस ग्रिल पर रखें। 5 मिनट पकाएँ। चिकन और प्याज़ को पलटें और 3 मिनट ग्रिल करें। चिकन और प्याज़ पर बारबेक्यू सॉस चम्मच से डालें और 2 मिनट ग्रिल करें। मीट थर्मामीटर 165 डिग्री F दिखाए तो चिकन पूरी तरह पका हुआ है। इसे प्लेट में निकालें। दो काँटों से चिकन को रेशों में तोड़ें। प्याज़ को छल्लों में अलग करें।","इस बीच, टॉर्टिला को फ़ॉइल में लपेटें और 3 मिनट के लिए ग्रिल पर रखें ताकि वे अंदर तक गरम हो जाएँ। हर टॉर्टिला में थोड़ा चिकन और प्याज़ भरें और रैप के रूप में लपेटें।","लेट्यूस को दो प्लेटों में बाँटें और ऊपर कटे हुए टमाटर रखें। परोसें।"]))
r.append(R(6566587,"जड़ी-बूटी और जैतून के तेल वाले मसले हुए आलू",
"मधुमेह होने का मतलब यह नहीं कि आपको स्टार्च वाले खाद्य पदार्थ पूरी तरह छोड़ने होंगे। आप उन्हें सही मात्रा में अब भी खा सकते हैं! मसले हुए आलू की यह रेसिपी मक्खन और क्रीम को छोड़ देती है और ज़्यादा सेहतमंद सामग्री का उपयोग करती है, जिससे बना व्यंजन फिर भी स्वादिष्ट और स्वाद से भरपूर है।",
"6","½ कप",
["10 साबुत बेबी गोल्डन आलू (कुल लगभग 1 पाउंड, रगड़कर साफ़ किए हुए और चार टुकड़ों में कटे हुए)","1/4 कप नीबू का रस (ताज़ा निचोड़ा हुआ)","2 बड़े चम्मच एक्स्ट्रा वर्जिन जैतून का तेल","1/4 कप ताज़ा धनिया पत्ती (बारीक कटी हुई)","1/4 कप ताज़ा सोआ (बारीक कटा हुआ)","1/2 छोटा चम्मच समुद्री नमक या कोशर नमक","1/4 छोटा चम्मच ताज़ी पिसी काली मिर्च","1 बड़ा चम्मच नीबू का छिलका (कसा हुआ)"],
["आलू को एक बड़े बर्तन में रखें और पानी से ढकें। तेज़ आँच पर उबाल आने दें, आँच मध्यम करें और बिना ढके 10-15 मिनट पकाएँ, या जब तक नरम न हो जाएँ। पानी निथार दें। नीबू का रस और जैतून का तेल डालें और हाथ से या इलेक्ट्रिक मिक्सर से मसलना शुरू करें। जब मिश्रण चिकना और मलाईदार हो जाए, तो नीबू का छिलका, धनिया पत्ती, सोआ, नमक और काली मिर्च मिलाएँ। गरम परोसें।"]))
r.append(R(6567580,"भुनी हुई वसंत की सब्ज़ियों के साथ बेक्ड अंडे",
"यह रंग-बिरंगा शीट पैन नाश्ता भुनी हुई वसंत की सब्ज़ियों और बिल्कुल सही बेक किए अंडों के साथ दिन की संतुलित, सब्ज़ियों पर केंद्रित शुरुआत देता है। फ़ाइबर और पोषक तत्वों से भरपूर, यह ऐसा विकल्प है जो परिष्कृत कार्ब पर निर्भर हुए बिना रक्त ग्लूकोज़ (ब्लड शुगर) को स्थिर बनाए रखने में सहायक है। मधुमेह वाले लोगों के लिए आदर्श, यह पौष्टिक भी है और पहले से तैयार करना भी आसान है। यह कम कार्ब और शाकाहारी रेसिपी है।",
"4","1 1/2 कप भुनी सब्ज़ियाँ, प्रति सर्विंग 1 अंडा",
["1 कप शतावरी (एस्पैरेगस) (छँटी हुई और 1 इंच के टुकड़ों में कटी हुई)","1 कप चेरी टमाटर (आधे कटे हुए)","1 मध्यम तोरी (अर्धचंद्राकार टुकड़ों में कटी हुई)","1 मध्यम लाल शिमला मिर्च (टुकड़ों में कटी हुई)","1 छोटा लाल प्याज़ (पतले स्लाइस में कटा हुआ)","2 कली लहसुन (बारीक कटी हुई)","2 छोटे चम्मच जैतून का तेल","1 छोटा चम्मच सूखा ओरेगानो","1/2 छोटा चम्मच काली मिर्च (पिसी हुई)","1/4 छोटा चम्मच नमक","1 कप बेबी पालक (पत्तियाँ)","4 बड़े अंडे","1/4 कप ताज़ी तुलसी (सजाने के लिए)","1 स्प्रे, 0.25 ग्राम नॉनस्टिक कुकिंग स्प्रे"],
["अपने ओवन को 400°F पर पहले से गरम करें।","एक बड़े मिक्सिंग बाउल में शतावरी, चेरी टमाटर, तोरी, शिमला मिर्च, लाल प्याज़ और लहसुन मिलाएँ।","ऊपर से जैतून का तेल डालें और सूखा ओरेगानो, काली मिर्च और नमक छिड़कें। सब्ज़ियों पर बराबर लगने तक मिलाएँ।","एक बड़ी शीट पैन पर कुकिंग स्प्रे की हल्की परत लगाएँ। मसाला लगी सब्ज़ियों को शीट पैन पर एक परत में फैलाएँ। पहले से गरम ओवन में 15-20 मिनट भूनें, या जब तक सब्ज़ियाँ नरम और हल्की कैरामेलाइज़्ड न हो जाएँ।","शीट पैन को ओवन से निकालें और भुनी हुई सब्ज़ियों पर बेबी पालक बिखेर दें। गर्मी से पालक थोड़ा गल जाएगा।","सब्ज़ियों के बीच चार छोटे गड्ढे बनाएँ और हर गड्ढे में सावधानी से एक अंडा तोड़कर डालें।","शीट पैन को वापस ओवन में रखें और 7-10 मिनट और बेक करें, या जब तक अंडे की सफ़ेदी जम न जाए और ज़र्दी आपकी पसंद के अनुसार पक न जाए।","सब्ज़ियों और अंडों के ऊपर ताज़ी तुलसी छिड़कें।"]))
r.append(R(6567846,"क्विनोआ तब्बूलेह",
"इस सलाद को तुरंत परोसा जा सकता है लेकिन इसे एक दिन पहले बनाना सबसे अच्छा है। क्विनोआ को जल्दी ठंडा करने के लिए उसे बेकिंग शीट पर फैलाएँ और ठंडा होने तक रेफ़्रिजरेटर में रखें।",
"6","¾ कप",
["1 कप क्विनोआ (सूखा)","1 1/2 कप पानी","1 बड़ा चम्मच एक्स्ट्रा वर्जिन जैतून का तेल","2 बड़े चम्मच नीबू का रस (1 मध्यम नीबू से)","1 छोटा चम्मच नीबू का छिलका (1 मध्यम नीबू से)","1 मध्यम टमाटर (बारीक टुकड़ों में कटा हुआ)","1 मध्यम खीरा (बीज निकाला हुआ और बारीक टुकड़ों में कटा हुआ)","1 कप ताज़ा अजमोद (कटा हुआ)","1/2 कप ताज़ा पुदीना (कटा हुआ)","1/2 छोटा चम्मच नमक (वैकल्पिक)","1/4 छोटा चम्मच काली मिर्च"],
["क्विनोआ को धोएँ और फिर 1 ½ कप पानी के साथ मिलाएँ। उबाल आने दें, फिर आँच धीमी करें। ढककर 15 मिनट पकाएँ या जब तक सारा तरल सोख न लिया जाए। काँटे से फुलाएँ और फिर पूरी तरह ठंडा होने दें।","ठंडे क्विनोआ को जैतून का तेल, नीबू का छिलका, नीबू का रस, टमाटर, खीरा, अजमोद, पुदीना, नमक (वैकल्पिक) और पिसी काली मिर्च के साथ मिलाएँ। रेफ़्रिजरेटर में रखें या परोसें।"]))
r.append(R(6567916,"मीटबॉल कबाब",
"ये मीटबॉल परिवार के लिए एक मज़ेदार भोजन बनाते हैं। या अगली बार जब आप मेहमानों को बुलाएँ तो इन्हें प्लैटर में स्टार्टर के रूप में परोसें।",
"6","2 कबाब",
["1 स्प्रे, 0.25 ग्राम नॉनस्टिक कुकिंग स्प्रे","4 बड़े अंडे की सफ़ेदी या 1 कप अंडे का विकल्प","2 बड़े चम्मच पारमेज़न चीज़ (कसा हुआ)","2 कली लहसुन (बारीक कटी हुई)","20 औंस कम चर्बी वाली कीमा टर्की (93% लीन)","1/2 छोटा चम्मच नमक","1/4 छोटा चम्मच पिसी काली मिर्च","12 साबुत बाँस की सींकें","24 साबुत ग्रेप या चेरी टमाटर","8 औंस क्रेमिनी (बेबी बेला) मशरूम (ज़रूरत हो तो 12 टुकड़े बनाने के लिए आधे काटें)","1 मध्यम प्याज़ (चार टुकड़ों में कटा हुआ, फिर हर टुकड़ा तीन भागों में कटा हुआ (कुल 12 प्याज़ के टुकड़े))","1/4 कप बाल्सैमिक सिरका","1 छोटा चम्मच जैतून का तेल"],
["ओवन को 375°F पर पहले से गरम करें। बेकिंग शीट पर कुकिंग स्प्रे लगाएँ। एक तरफ़ रख दें।","अंडे की सफ़ेदी, पारमेज़न चीज़, लहसुन, टर्की, नमक और काली मिर्च मिलाएँ। अच्छी तरह मिलाएँ और 24 मीटबॉल बनाएँ। मीटबॉल को कम से कम 30 मिनट रेफ़्रिजरेटर में रखें।","हर सींक पर बारी-बारी से 2 मीटबॉल, 2 टमाटर, मशरूम का 1 टुकड़ा और प्याज़ का 1 टुकड़ा पिरोएँ।","एक छोटे कटोरे में सिरका और जैतून का तेल फेंटकर मिलाएँ।","कबाब को बेकिंग शीट पर रखें और कबाब की सभी तरफ़ सिरके और जैतून के तेल के मिश्रण से ब्रश करें। मैरिनेड बचाकर रखें।","कबाब को 10 मिनट बेक करें। सभी तरफ़ फिर से मैरिनेड लगाएँ और 10-15 मिनट और बेक करें। मीटबॉल अंदर से कम से कम 165°F के तापमान तक पके होने चाहिए।"]))
r.append(R(6568402,"कड़ाही में बना कैरवे कॉर्नब्रेड",
"नोट: इस ब्रेड को नॉनस्टिक कुकिंग स्प्रे लगे 8 इंच के चौकोर बेकिंग पैन में भी तैयार किया जा सकता है। तब आपको 2 छोटे चम्मच वनस्पति तेल की ज़रूरत नहीं होगी।",
"16","1 फाँक",
["1 छोटा चम्मच कैरवे बीज (शाही जीरा)","1/4 कप और 2 छोटे चम्मच वनस्पति तेल (बाँटा हुआ)","1 कप कॉर्नमील","1 कप साबुत गेहूँ का आटा","1 1/2 छोटा चम्मच बेकिंग पाउडर","1/2 छोटा चम्मच बेकिंग सोडा","1/2 छोटा चम्मच नमक","2 बड़े अंडे","1 कप कम वसा वाली छाछ (बटरमिल्क)","1/4 कप शहद"],
["ओवन को 400°F पर पहले से गरम करें। एक छोटी, सूखी कड़ाही में मध्यम आँच पर कैरवे बीज को 2 से 3 मिनट भूनें, बस हल्का भूरा होने और खुशबू आने तक; अलग रख दें। जब ओवन गरम हो जाए, तो 9 इंच की कास्ट-आयरन कड़ाही में वनस्पति तेल के 2 छोटे चम्मच डालें। पैन को ओवन में 5 मिनट गरम करें।","इस बीच, एक बड़े कटोरे में कॉर्नमील, आटा, बेकिंग पाउडर, बेकिंग सोडा, नमक और कैरवे बीज मिलाएँ।","एक अलग कटोरे में अंडों को वायर व्हिस्क से फेंटें। छाछ, शहद और 1/4 कप वनस्पति तेल डालें।","गीली सामग्री को सूखी सामग्री में डालें और बस मिलने तक मिलाएँ।","घोल को सावधानी से गरम कड़ाही में डालें और 20 से 22 मिनट बेक करें, या जब तक कॉर्नब्रेड पूरी तरह पक न जाए और बीच में डाला गया केक टेस्टर या टूथपिक साफ़ न निकले। कॉर्नब्रेड को 5 मिनट ठंडा होने दें। 16 बराबर आकार की फाँकों में काटें और गरम परोसें।"]))
r.append(R(6568654,"छोले के साथ बटरनट स्क्वैश स्ट्यू",
"यह भरपेट स्ट्यू बटरनट स्क्वैश से बनता है, जो एक प्रकार का शीतकालीन स्क्वैश है और साल के ठंडे महीनों में मौसम में आता है। इसे सप्ताहांत में बनाएँ और बचा हुआ हफ़्ते के दौरान दोपहर के भोजन के लिए पैक करें।",
"8","1 कप",
["1 मध्यम बटरनट स्क्वैश","2 छोटे चम्मच जैतून का तेल","1 बड़ा प्याज़ (कटा हुआ)","3 कली लहसुन (बारीक कटी हुई)","1/2 पाउंड लाल आलू (बिना छिले और चार टुकड़ों में कटे हुए)","1 कप कम सोडियम वाला चिकन ब्रॉथ (कम वसा वाला, कम सोडियम वाला)","1 (14 औंस) डिब्बा डिब्बाबंद कटे हुए टमाटर (बिना निथारे, ज़्यादा स्वाद के लिए फ़ायर रोस्टेड आज़माएँ)","3/4 छोटा चम्मच सूखा ओरेगानो","1/8 छोटा चम्मच कोशर नमक","1/8 छोटा चम्मच ताज़ी पिसी काली मिर्च, स्वादानुसार","1 (15 औंस) डिब्बा छोले (काबुली चने) (पानी निथारे और धुले हुए)","2 बड़े चम्मच प्राकृतिक मलाईदार पीनट बटर (चिकना होने तक अच्छी तरह चलाया हुआ)","2 बड़े चम्मच अजमोद (कटा हुआ)"],
["बटरनट स्क्वैश तैयार करें। पूरे स्क्वैश को माइक्रोवेव ओवन के फ़र्श या रैक पर रखें। स्क्वैश को 5 मिनट माइक्रोवेव करें। सावधानी से निकालें और संभालने लायक ठंडा होने तक छोड़ दें। तेज़ चाकू से स्क्वैश को आड़ा आधा काटें। चाकू से हर आधे का छिलका उतारें, केवल छिलका ही निकालने के लिए पास से काटें। हर आधे को लंबाई में काटें। स्क्वैश के निचले आधे हिस्से से बीज निकालें और फेंक दें। सारे स्क्वैश को 1 इंच के टुकड़ों में काटें। अलग रख दें। यह प्रक्रिया सख़्त बटरनट स्क्वैश को काटना आसान बनाती है क्योंकि यह छिलके को ढीला करने में मदद करती है।","एक बड़े डच ओवन में मध्यम आँच पर तेल गरम करें। प्याज़ और लहसुन डालें और 5-6 मिनट भूनें। बटरनट स्क्वैश और आलू डालें और प्याज़ और लहसुन के साथ लपेटने के लिए चलाएँ। ब्रॉथ, रस सहित टमाटर, ओरेगानो, नमक और काली मिर्च डालें। उबाल आने दें। आँच कम करके धीमी करें, ढक दें और मध्यम-धीमी आँच पर लगभग 20 मिनट पकाएँ, जब तक स्क्वैश और आलू नरम न हो जाएँ। कुछ स्क्वैश बहुत नरम हो सकता है।","छोले और पीनट बटर को धीरे से मिलाएँ और 5 मिनट पकाएँ। कटे हुए अजमोद से सजाएँ।"]))
r.append(R(6569048,"\"सॉसेज\" क्रम्बल्स, शिमला मिर्च और प्याज़ के साथ शीट-पैन पत्तागोभी पिज़्ज़ा",
"सब्ज़ियों पर केंद्रित यह पत्तागोभी पिज़्ज़ा आटे की जगह भुनी हुई पत्तागोभी की फाँकों का उपयोग करता है, जिससे कार्बोहाइड्रेट कम रहता है और स्वाद, प्रोटीन और बिना स्टार्च वाली सब्ज़ियाँ भरपूर मिलती हैं। कॉटेज चीज़ और कम वसा वाले मोज़ेरेला का मिश्रण मलाईदार, पिघला हुआ स्वाद देता है। टोफ़ू \"सॉसेज\" क्रम्बल्स स्वादिष्ट पौधों से मिलने वाला प्रोटीन जोड़ते हैं, और भुने हुए प्याज़ और शिमला मिर्च फ़ाइबर और सब्ज़ियों की मात्रा बढ़ाते हैं, जिससे यह एक मधुमेह के अनुकूल, शाकाहारी मुख्य व्यंजन बनता है जो भरपेट और संतोषजनक है। ऊपर से खट्टी फ़ैट-फ़्री ग्रीक योगर्ट रैंच की धार डाली जाती है, जो मलाईदार, प्रोटीन से भरपूर टॉपिंग है।",
"4","टॉपिंग के साथ 2 पत्तागोभी के गोले + 2 बड़े चम्मच योगर्ट सॉस",
["1 बड़ी हरी पत्तागोभी (लगभग 2 ½ पाउंड, लगभग 3/8 इंच मोटे 8 गोलों में कटी हुई)","2 स्प्रे, 0.50 ग्राम जैतून के तेल का कुकिंग स्प्रे","1 (14 औंस) डिब्बा डिब्बाबंद साबुत टमाटर (बिना नमक मिलाए)","1 कली लहसुन (बारीक कटी हुई)","1 छोटा चम्मच सूखा ओरेगानो","1/2 छोटा चम्मच काली मिर्च","14 औंस एक्स्ट्रा फ़र्म टोफ़ू (दबाकर पानी निकाला हुआ और चूरा किया हुआ)","1 बड़ा चम्मच कम सोडियम वाला सोया सॉस (या तामारी)","1/4 छोटा चम्मच सौंफ़ के बीज (कुटे हुए)","1/4 छोटा चम्मच कुटी हुई लाल मिर्च के फ़्लेक्स","1 छोटा चम्मच लहसुन पाउडर (बाँटकर उपयोग)","1/2 कप कॉटेज चीज़ (फ़ैट-फ़्री)","1/2 कप मोज़ेरेला चीज़ (कम वसा वाला, कसा हुआ)","1 कप शिमला मिर्च (स्लाइस की हुई)","1 कप प्याज़ (पीला या सफ़ेद, पतले स्लाइस में कटा हुआ)","1/3 कप ताज़ी तुलसी (पत्तियाँ)","1/2 कप सादा फ़ैट-फ़्री ग्रीक योगर्ट","1 बड़ा चम्मच नीबू का रस","1 छोटा चम्मच सूखा सोआ","1/2 छोटा चम्मच प्याज़ पाउडर","1 बड़ा चम्मच पानी"],
["एक मध्यम कटोरे में टमाटर को हाथ से मसलें या ब्लेंडर में हल्के से पल्स करें जब तक वे ज़्यादातर चिकने न हो जाएँ। कटा हुआ लहसुन, ½ छोटा चम्मच ओरेगानो और ¼ छोटा चम्मच काली मिर्च मिलाएँ। अलग रख दें।","ओवन को 425°F पर पहले से गरम करें। दो बड़ी शीट पैन पर बेकिंग पेपर बिछाएँ। पत्तागोभी के गोलों को एक परत में सजाएँ और दोनों तरफ़ कुकिंग स्प्रे की हल्की परत लगाएँ। पत्तागोभी के चारों ओर शिमला मिर्च और प्याज़ बिखेर दें। 20–25 मिनट तक भूनें, बीच में पत्तागोभी को पलटें, जब तक वह नरम और हल्की भूरी न हो जाए।","जब पत्तागोभी भुन रही हो, एक सूखी कड़ाही को मध्यम आँच पर गरम करें। चूरा किया हुआ टोफ़ू डालें और नमी सुखाने के लिए 2–3 मिनट पकाएँ। सोया सॉस, सौंफ़ के बीज, लहसुन पाउडर, बचा हुआ ½ छोटा चम्मच ओरेगानो, बची हुई ¼ छोटा चम्मच काली मिर्च और कुटी हुई लाल मिर्च के फ़्लेक्स डालें। बार-बार चलाते हुए तब तक पकाएँ जब तक वह हल्का भूरा और सुगंधित न हो जाए, लगभग 8–10 मिनट।","फ़ैट-फ़्री ग्रीक योगर्ट, नीबू का रस, सोआ, बचा हुआ 1/2 छोटा चम्मच लहसुन पाउडर और प्याज़ पाउडर को फेंटकर मिलाएँ। धार डालने लायक गाढ़ापन आने तक 1 बड़ा चम्मच करके पानी डालें। अलग रख दें।","पत्तागोभी के गोलों को ओवन से निकालें। हर गोले पर 3 बड़े चम्मच टमाटर का सॉस डालें। हर गोले पर सॉस के ऊपर 2 बड़े चम्मच फ़ैट-फ़्री कॉटेज चीज़ बराबर डालें, फिर पिज़्ज़ा पर कम वसा वाला मोज़ेरेला बराबर छिड़कें। ऊपर टोफ़ू क्रम्बल्स, शिमला मिर्च और प्याज़ रखें। वापस ओवन में रखें और 10–15 मिनट बेक करें, जब तक चीज़ पिघल न जाए और सब कुछ अंदर तक गरम न हो जाए।","पिज़्ज़ा को 5 मिनट ठंडा होने दें, फिर ऊपर तुलसी की पत्तियाँ बिखेरें। परोसने से ठीक पहले हर पिज़्ज़ा पर योगर्ट रैंच की धार डालें। प्रति व्यक्ति पत्तागोभी के 2 पिज़्ज़ा गोले परोसें।"]))
r.append(R(6569922,"पकी हुई मसूर की दाल",
"पकी हुई मसूर की दाल की पोषण संबंधी जानकारी",
"1","1/2 कप पकी हुई",["1/2 कप पकी हुई मसूर की दाल (¼ कप सूखी का उपयोग करें)"],[]))
r.append(R(6570315,"ब्रुशेटा भरी तोरी की नावें",
"आपको अपनी थाली का आधा हिस्सा बिना स्टार्च वाली सब्ज़ियों से भरने की कोशिश करनी चाहिए, जिसका मतलब है कि आपको रचनात्मक होना होगा ताकि आप एक ही रेसिपी से ऊब न जाएँ। ये तोरी की नावें तेज़, आसान और भाप में पकी सब्ज़ियों से एक स्वादिष्ट बदलाव हैं।",
"4","1/2 तोरी",
["2 बड़ी तोरी","2 छोटे चम्मच जैतून का तेल","1/8 छोटा चम्मच काली मिर्च","1/2 कप जार वाला ब्रुशेटा","4 छोटे चम्मच पारमेज़न चीज़ (कसा हुआ)"],
["तोरी के सिरे काटकर फेंक दें। हर तोरी को लंबाई में आधा काटें।","चम्मच से तोरी के बीच का हिस्सा निकालें और तली में एक पतली परत छोड़ दें ताकि \"नाव\" में भरावन भरा जा सके। निकाले हुए गूदे को एक छोटे कटोरे में रखें; अलग रख दें।","एक मध्यम बर्तन में नमक वाला पानी उबालें। तोरी की नावों को बस नरम होना शुरू होने तक ब्लैंच करें, लगभग 2-3 मिनट। तुरंत तोरी की नावों को बर्फ़ के पानी के कटोरे में डालें। तोरी का पानी निथारें और उसे बेकिंग शीट पर रखें।","एक मध्यम कड़ाही में मध्यम आँच पर जैतून का तेल गरम करें। बचे हुए तोरी के गूदे पर काली मिर्च छिड़कें; इसे पैन में डालें और लगभग 6-8 मिनट भूनें। ब्रुशेटा मिलाएँ; आँच कम करें और 3 मिनट धीमी आँच पर पकाएँ।","ब्रुशेटा के मिश्रण को चारों तोरी की नावों में बराबर चम्मच से भरें। हर तोरी की नाव पर 1 छोटा चम्मच पारमेज़न चीज़ छिड़कें।","ब्रॉयलर चालू करें। भरी हुई तोरी की नावों को हल्का सुनहरा होने तक ब्रॉइल करें, लगभग 2-3 मिनट; जलने से बचाने के लिए ध्यान से देखते रहें।"]))
save(5,r)
